/*
 * OpenXR motion controller input.
 *
 * Everything here ends up in the st_* interface that share/state.c already
 * exposes to keyboards, mice and joysticks, using the button and axis
 * numbers the configuration already defines. That is the same trick
 * ball/main.c:607-627 plays to turn a tilt sensor into D-pad presses, and it
 * means none of the game's states need to know a headset is involved.
 *
 * The one thing without an existing equivalent is the pointer ray, which
 * lands on the world-locked interface panel and is delivered as mouse
 * motion and clicks. share/gui.c's hit testing is then reused untouched.
 */

#include <math.h>
#include <string.h>

#include <SDL.h>

#include "vec3.h"
#include "hmd.h"
#include "hmd_openxr.h"
#include "vr.h"
#include "vr_input.h"
#include "config.h"
#include "state.h"
#include "video.h"
#include "log.h"

