#define HAND_L 0
#define HAND_R 1
#define HANDS  2

static XrActionSet act_set;

static XrAction act_tilt;               /* left thumbstick,  Vector2f */
static XrAction act_look;               /* right thumbstick, Vector2f */
static XrAction act_aim [HANDS];        /* pointing pose              */
static XrAction act_grip;               /* right grip pose, for tilt  */
static XrAction act_select;             /* trigger                    */
static XrAction act_back;               /* B                          */
static XrAction act_start;              /* X                          */
static XrAction act_option;             /* Y                          */
static XrAction act_cam [HANDS];        /* grip squeeze               */

static XrSpace  spc_aim [HANDS];
static XrSpace  spc_grip;

static int ready;                       /* actions built and attached */
static int failed;                      /* and if not, do not retry   */

/*---------------------------------------------------------------------------*/

#define XR_TRY(expr)                                                    \
    do {                                                                \
        XrResult res_ = (expr);                                         \
        if (XR_FAILED(res_))                                            \
        {                                                               \
            log_printf("VR input: %s failed (%d)\n", #expr, (int) res_); \
            return 0;                                                   \
        }                                                               \
    } while (0)

static XrPath path(const char *s)
{
    XrPath p = XR_NULL_PATH;

    xrStringToPath(hmd_xr_instance(), s, &p);

    return p;
}

static int make_action(XrAction *a, XrActionType type, const char *name,
                       const char *label)
{
    XrActionCreateInfo info;

    memset(&info, 0, sizeof (info));
    info.type       = XR_TYPE_ACTION_CREATE_INFO;
    info.actionType = type;

    strncpy(info.actionName,          name,  XR_MAX_ACTION_NAME_SIZE - 1);
    strncpy(info.localizedActionName, label, XR_MAX_LOCALIZED_ACTION_NAME_SIZE - 1);

    XR_TRY(xrCreateAction(act_set, &info, a));

    return 1;
}

static int make_pose_space(XrSpace *s, XrAction a)
{
    XrActionSpaceCreateInfo info;

    memset(&info, 0, sizeof (info));
    info.type   = XR_TYPE_ACTION_SPACE_CREATE_INFO;
    info.action = a;
    info.poseInActionSpace.orientation.w = 1.0f;

    XR_TRY(xrCreateActionSpace(hmd_xr_session(), &info, s));

    return 1;
}

/*
 * Suggest one interaction profile's worth of bindings. A runtime is free to
 * reject a profile it does not know, which is why the result is not fatal:
 * the Touch bindings are what a Quest will use, and the simple controller is
 * a fallback that costs nothing to offer.
 */

static void suggest(const char *profile,
                    const XrActionSuggestedBinding *b, int n)
{
    XrInteractionProfileSuggestedBinding s;

    memset(&s, 0, sizeof (s));
    s.type                   = XR_TYPE_INTERACTION_PROFILE_SUGGESTED_BINDING;
    s.interactionProfile     = path(profile);
    s.countSuggestedBindings = (uint32_t) n;
    s.suggestedBindings      = b;

    if (XR_FAILED(xrSuggestInteractionProfileBindings(hmd_xr_instance(), &s)))
        log_printf("VR input: runtime declined bindings for %s\n", profile);
}

static int init_actions(void)
{
    XrActionSetCreateInfo set_info;
    XrSessionActionSetsAttachInfo attach;

    memset(&set_info, 0, sizeof (set_info));
    set_info.type = XR_TYPE_ACTION_SET_CREATE_INFO;
    strcpy(set_info.actionSetName,          "gameplay");
    strcpy(set_info.localizedActionSetName, "Gameplay");
    set_info.priority = 0;

    XR_TRY(xrCreateActionSet(hmd_xr_instance(), &set_info, &act_set));

    if (!make_action(&act_tilt,   XR_ACTION_TYPE_VECTOR2F_INPUT, "tilt",   "Tilt the floor")   ||
        !make_action(&act_look,   XR_ACTION_TYPE_VECTOR2F_INPUT, "look",   "Turn the camera")  ||
        !make_action(&act_aim[HAND_L], XR_ACTION_TYPE_POSE_INPUT, "aim_left",  "Point (left)")  ||
        !make_action(&act_aim[HAND_R], XR_ACTION_TYPE_POSE_INPUT, "aim_right", "Point (right)") ||
        !make_action(&act_grip,   XR_ACTION_TYPE_POSE_INPUT,     "wrist",  "Tilt by wrist")    ||
        !make_action(&act_select, XR_ACTION_TYPE_BOOLEAN_INPUT,  "select", "Select")           ||
        !make_action(&act_back,   XR_ACTION_TYPE_BOOLEAN_INPUT,  "back",   "Back")             ||
        !make_action(&act_start,  XR_ACTION_TYPE_BOOLEAN_INPUT,  "start",  "Pause")            ||
        !make_action(&act_option, XR_ACTION_TYPE_BOOLEAN_INPUT,  "option", "Options")          ||
        !make_action(&act_cam[HAND_L], XR_ACTION_TYPE_BOOLEAN_INPUT, "camera_left",  "Camera left")  ||
        !make_action(&act_cam[HAND_R], XR_ACTION_TYPE_BOOLEAN_INPUT, "camera_right", "Camera right"))
        return 0;

    {
        const XrActionSuggestedBinding touch[] = {
            { act_tilt,   path("/user/hand/left/input/thumbstick")     },
            { act_look,   path("/user/hand/right/input/thumbstick")    },
            { act_aim[HAND_L], path("/user/hand/left/input/aim/pose")  },
            { act_aim[HAND_R], path("/user/hand/right/input/aim/pose") },
            { act_grip,   path("/user/hand/right/input/grip/pose")     },
            { act_select, path("/user/hand/right/input/trigger/value") },
            { act_select, path("/user/hand/left/input/trigger/value")  },
            { act_select, path("/user/hand/right/input/a/click")       },
            { act_back,   path("/user/hand/right/input/b/click")       },
            { act_start,  path("/user/hand/left/input/x/click")        },
            { act_option, path("/user/hand/left/input/y/click")        },
            { act_cam[HAND_L], path("/user/hand/left/input/squeeze/value")  },
            { act_cam[HAND_R], path("/user/hand/right/input/squeeze/value") },
        };

        const XrActionSuggestedBinding simple[] = {
            { act_aim[HAND_L], path("/user/hand/left/input/aim/pose")  },
            { act_aim[HAND_R], path("/user/hand/right/input/aim/pose") },
            { act_grip,   path("/user/hand/right/input/grip/pose")     },
            { act_select, path("/user/hand/right/input/select/click")  },
            { act_select, path("/user/hand/left/input/select/click")   },
            { act_back,   path("/user/hand/right/input/menu/click")    },
            { act_start,  path("/user/hand/left/input/menu/click")     },
        };

        suggest("/interaction_profiles/oculus/touch_controller",
                touch, (int) (sizeof (touch) / sizeof (touch[0])));
        suggest("/interaction_profiles/khr/simple_controller",
                simple, (int) (sizeof (simple) / sizeof (simple[0])));
    }

    if (!make_pose_space(&spc_aim[HAND_L], act_aim[HAND_L]) ||
        !make_pose_space(&spc_aim[HAND_R], act_aim[HAND_R]) ||
        !make_pose_space(&spc_grip,        act_grip))
        return 0;

    memset(&attach, 0, sizeof (attach));
    attach.type                = XR_TYPE_SESSION_ACTION_SETS_ATTACH_INFO;
    attach.countActionSets     = 1;
    attach.actionSets          = &act_set;

    XR_TRY(xrAttachSessionActionSets(hmd_xr_session(), &attach));

    log_printf("VR input: action set attached\n");

    return 1;
}

