static int get_vec2(XrAction a, float *x, float *y)
{
    XrActionStateGetInfo get;
    XrActionStateVector2f st;

    memset(&get, 0, sizeof (get));
    get.type   = XR_TYPE_ACTION_STATE_GET_INFO;
    get.action = a;

    memset(&st, 0, sizeof (st));
    st.type = XR_TYPE_ACTION_STATE_VECTOR2F;

    if (XR_FAILED(xrGetActionStateVector2f(hmd_xr_session(), &get, &st)) ||
        !st.isActive)
        return 0;

    *x = st.currentState.x;
    *y = st.currentState.y;

    return 1;
}

/* Report a button only when it changes, which is what st_buttn() expects. */

static int get_edge(XrAction a, int *down)
{
    XrActionStateGetInfo get;
    XrActionStateBoolean st;

    memset(&get, 0, sizeof (get));
    get.type   = XR_TYPE_ACTION_STATE_GET_INFO;
    get.action = a;

    memset(&st, 0, sizeof (st));
    st.type = XR_TYPE_ACTION_STATE_BOOLEAN;

    if (XR_FAILED(xrGetActionStateBoolean(hmd_xr_session(), &get, &st)) ||
        !st.isActive || !st.changedSinceLastSync)
        return 0;

    *down = st.currentState ? 1 : 0;

    return 1;
}

static int get_pose(XrSpace space, XrPosef *pose)
{
    XrSpaceLocation loc;

    memset(&loc, 0, sizeof (loc));
    loc.type = XR_TYPE_SPACE_LOCATION;

    if (XR_FAILED(xrLocateSpace(space, hmd_xr_space(), hmd_xr_time(), &loc)))
        return 0;

    if (!(loc.locationFlags & XR_SPACE_LOCATION_POSITION_VALID_BIT) ||
        !(loc.locationFlags & XR_SPACE_LOCATION_ORIENTATION_VALID_BIT))
        return 0;

    *pose = loc.pose;

    return 1;
}

/* The three axes of a pose's orientation, as the renderer would see them. */

static void pose_basis(const XrPosef *p, float right[3], float fwd[3])
{
    const float x = p->orientation.x;
    const float y = p->orientation.y;
    const float z = p->orientation.z;
    const float w = p->orientation.w;

    if (right)
    {
        right[0] = 1.0f - 2.0f * (y * y + z * z);
        right[1] =        2.0f * (x * y + z * w);
        right[2] =        2.0f * (x * z - y * w);
    }

    /* Forward is -Z, as it is everywhere else in this codebase. */

    if (fwd)
    {
        fwd[0] = -(       2.0f * (x * z + y * w));
        fwd[1] = -(       2.0f * (y * z - x * w));
        fwd[2] = -(1.0f - 2.0f * (x * x + y * y));
    }
}

/* How far an axis of the controller has tipped off horizontal, in degrees. */

static float tip_deg(float y)
{
    if (y >  1.0f) y =  1.0f;
    if (y < -1.0f) y = -1.0f;

    return V_DEG(asinf(y));
}

/*---------------------------------------------------------------------------*/

/* Only report an axis when it actually moves, as a joystick would. */

static void push_stick(int axis, float v, float *last)
{
    if (fabsf(v - *last) > 0.01f)
    {
        *last = v;
        st_stick(axis, v);
    }
}

static void poll_sticks(void)
{
    static float last_x0 = 0.0f, last_y0 = 0.0f, last_x1 = 0.0f;
    static int   turning = 0;

    float x, y;

    /*
     * The left stick always reports, because it is also how menus are
     * navigated. In wrist mode poll_wrist() runs afterwards and overrides
     * it, which only affects the playing state -- nothing else listens for
     * an angle.
     */

    if (get_vec2(act_tilt, &x, &y))
    {
        /* A thumbstick reads y as up; a joystick axis reads it as down. */

        push_stick(config_get_d(CONFIG_JOYSTICK_AXIS_X0), x, &last_x0);
        push_stick(config_get_d(CONFIG_JOYSTICK_AXIS_Y0), -y, &last_y0);
    }

    /*
     * The right stick is a two-way switch rather than an axis: pushing it
     * left or right asks for one step of camera rotation, and there is
     * nothing up or down -- a vertical camera swing in a headset is both
     * unpleasant and, with the chase camera already level, pointless.
     *
     * The two thresholds are deliberately apart. A stick resting near one
     * of them would otherwise chatter out a step every few frames, which
     * with a stepped turn is a spinning room rather than a small wobble.
     */

    if (get_vec2(act_look, &x, &y))
    {
        if (turning == 0)
        {
            if (x > +0.6f) turning = +1;
            if (x < -0.6f) turning = -1;
        }
        else if (fabsf(x) < 0.4f)
            turning = 0;

        push_stick(config_get_d(CONFIG_JOYSTICK_AXIS_X1),
                   (float) turning, &last_x1);
    }
}

static void poll_buttons(void)
{
    static const struct
    {
        XrAction *action;
        const int *button;
    } map[] = {
        { &act_back,        &CONFIG_JOYSTICK_BUTTON_B      },
        { &act_start,       &CONFIG_JOYSTICK_BUTTON_START  },
        { &act_option,      &CONFIG_JOYSTICK_BUTTON_SELECT },
        { &act_cam[HAND_L], &CONFIG_JOYSTICK_BUTTON_L1     },
        { &act_cam[HAND_R], &CONFIG_JOYSTICK_BUTTON_R1     },
    };

    size_t i;
    int down;

    /*
     * The trigger is both a click on whatever the pointer is over and the
     * A button, which is what makes a menu usable either by pointing at it
     * or by moving a highlight with the stick.
     */

    if (get_edge(act_select, &down))
        st_click(SDL_BUTTON_LEFT, down);

    for (i = 0; i < sizeof (map) / sizeof (map[0]); i++)
        if (get_edge(*map[i].action, &down))
            st_buttn(config_get_d(*map[i].button), down);
}

static void poll_pointer(void)
{
    static int last_x, last_y, have_last;

    XrPosef pose;
    float fwd[3];
    float o[3];
    int x, y;

    /* Prefer the right hand, and fall back to the left when it is not
     * being tracked, which is what a left-handed player will see. */

    if (!get_pose(spc_aim[HAND_R], &pose) &&
        !get_pose(spc_aim[HAND_L], &pose))
        return;

    pose_basis(&pose, NULL, fwd);

    o[0] = pose.position.x;
    o[1] = pose.position.y;
    o[2] = pose.position.z;

    if (!vr_panel_hit(o, fwd, video.device_w, video.device_h, &x, &y))
        return;

    st_point(x, y, have_last ? x - last_x : 0, have_last ? y - last_y : 0);

    last_x    = x;
    last_y    = y;
    have_last = 1;
}

static void poll_wrist(void)
{
    XrPosef pose;
    float right[3], fwd[3];

    if (!config_get_d(CONFIG_VR_CONTROL))
        return;

    if (!get_pose(spc_grip, &pose))
        return;

    pose_basis(&pose, right, fwd);

    /*
     * game_set_ang() clamps to ANGLE_BOUND, so tipping the controller twenty
     * degrees is full deflection -- about what it takes to feel like tilting
     * a tray.
     */

    st_angle(tip_deg(fwd[1]), tip_deg(-right[1]));
}

/*---------------------------------------------------------------------------*/

void vr_input_init(void)
{
    ready  = 0;
    failed = 0;
}

void vr_input_free(void)
{
    if (act_set != XR_NULL_HANDLE)
        xrDestroyActionSet(act_set);

    act_set = XR_NULL_HANDLE;
    ready   = 0;
    failed  = 0;
}

void vr_input_poll(void)
{
    XrActiveActionSet active;
    XrActionsSyncInfo sync;

    if (failed || !hmd_stat() || !hmd_xr_time())
        return;

    if (!ready)
    {
        if (!(ready = init_actions()))
        {
            log_printf("VR input: giving up on the controllers\n");
            failed = 1;
            return;
        }
    }

    memset(&active, 0, sizeof (active));
    active.actionSet     = act_set;
    active.subactionPath = XR_NULL_PATH;

    memset(&sync, 0, sizeof (sync));
    sync.type                  = XR_TYPE_ACTIONS_SYNC_INFO;
    sync.countActiveActionSets = 1;
    sync.activeActionSets      = &active;

    /* Not being focused is reported as success with everything inactive,
     * so there is nothing to special-case here. */

    if (XR_FAILED(xrSyncActions(hmd_xr_session(), &sync)))
        return;

    poll_sticks();
    poll_buttons();
    poll_pointer();
    poll_wrist();
}

